CREATE OR REPLACE FUNCTION public.mha_admin_user_access_catalog()\n RETURNS jsonb\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO ''\nAS $function$\nbegin\n if auth.uid() is null or not exists(select 1 from public.mha_super_admin_identity sa join public.mha_user_profile u on u.user_id=sa.user_id where sa.user_id=auth.uid() and u.is_active and u.is_super_admin) then raise exception 'Super Admin access required' using errcode='42501';end if;\n return jsonb_build_object(\n 'users',coalesce((select jsonb_agg(jsonb_build_object('user_id',u.user_id,'username',u.username,'company_id',u.company_id,'role_id',u.role_id,'default_store_id',u.default_store_id,'is_active',u.is_active,'is_super_admin',u.is_super_admin,'email',a.email) order by u.username) from public.mha_user_profile u join auth.users a on a.id=u.user_id),'[]'::jsonb),\n 'assignments',coalesce((select jsonb_agg(jsonb_build_object('user_id',user_id,'store_id',store_id)) from public.mha_user_store),'[]'::jsonb),\n 'companies',coalesce((select jsonb_agg(jsonb_build_object('id',id,'company_name',company_name,'is_active',is_active)) from public.mha_company),'[]'::jsonb),\n 'stores',coalesce((select jsonb_agg(jsonb_build_object('id',id,'company_id',company_id,'store_name',store_name,'store_code',store_code,'is_active',is_active)) from public.mha_store),'[]'::jsonb),\n 'roles',coalesce((select jsonb_agg(jsonb_build_object('id',id,'company_id',company_id,'role_name',role_name,'is_active',is_active)) from public.mha_role),'[]'::jsonb)\n );\nend $function$\n